    "dc.tRise": "این بالا رفتن، زنگ خطرت است که کارش را می‌کند: <b>بلند، نه لزوماً درست</b>. لازم نیست کاری با آن بکنی. بمان و خط را تماشا کن.",
    "dc.tFall": "می‌بینی پایین می‌آید؟ فرار نکردی، بحث نکردی، حواست را پرت نکردی — فقط <b>ماندی</b>. این پایین آمدن، خوگیری است: بدنت همین حالا دارد به‌روز می‌شود.",
    "dc.tNewGround": "نزدیک‌تر یعنی یک موج تازه — کوچک‌تر از اولی. بالا، بعد دوباره پایین. نردبان همین‌طور بالا رفته می‌شود: هر بار یک موج.",
    "dc.tSettled": "<b>فروکش کرد.</b> همان {dog}، همان فاصله — زنگ خطری آرام‌تر. نه با آن جنگیدی، نه از آن فرار کردی. ماندی، و بدنت بقیه‌اش را انجام داد.",
    "dc.tEscape": "عقب کشیدن زنگ خطر را سریع پایین آورد. همین آسودگی است که ترس را زنده نگه می‌دارد: مغز آن را <b>«درست به‌موقع فرار کردم»</b> ثبت می‌کند و هیچ‌وقت فرصت نمی‌کند یاد بگیرد که سگ مشکلی نداشت. هر وقت آماده بودی برگرد — زنگ خطر همان‌جایی است که رهایش کردی.",
    "dc.tBarkHab": "به قله‌ها نگاه کن: هر پارس کمی آرام‌تر از قبلی به تو می‌خورد. همان پارس — زنگ خطرت دارد یاد می‌گیرد که فقط صداست.",
    "dc.tFirstRead": "خواندن سگ نیمی از درمان است. ترس هر نشانهٔ سگ را <b>خطر</b> می‌خواند؛ سگ‌های واقعی بیشتر وقت‌ها می‌گویند <b>آرامم</b> یا <b>کنجکاوم</b>.",
    "dc.noticed": "{dog} متوجهت شد. نگاه می‌کند — نگاه فقط همین است. ببین بعدش چه می‌کند.",
    "dc.stood": "{dog} بلند شد — گوش‌ها بالا، چشم به تو. هشیار یعنی حمله نیست. بمان و ببین چه می‌کند.",
    "dc.sniffHello": "{dog} آمد تا با بو کشیدن سلام کند. آرام بمان — دارد با بینی‌اش تو را می‌شناسد.",
    "dc.sniffDone": "این سلامِ یک سگ بود. چیز دیگری در راه نبود.",
    "dc.hintSniff": "{dog} دارد برای سلام بو می‌کشد — سگ‌ها این‌طور آشنا می‌شوند. آرام بمان، یا روی او {click} تا دستت را جلو ببری.",
    "dc.hintPet": "{dog} درست کنارت است · اگر خواستی، روی او {click} تا نوازشش کنی",
    "dc.hintInvite": "روی {dog} {click} تا دعوتش کنی نزدیک‌تر بیاید — یا فقط بمان",
    "dc.warnPrompt": "{dog} خشک شد و غرید — یک هشدار. مکث کن و نگاهت را نرم کن. سگ‌ها غرش می‌کنند تا مجبور نشوند گاز بگیرند.",
    "dc.warnDone": "خودش را تکاند — تمام شد. یک هشدار را خواندی و لحظه‌ای به او فرصت دادی. هشدار همیشه فقط همین را می‌خواهد.",
    "dc.kodaTired": "انرژی {dog} ته کشید. آن‌همه سروصدا — و آخرش این است: یک سگ خسته و مهربان.",
    "dogs.lookaway2": "سرش را برگرداند — یعنی مؤدبانه می‌گوید «مشکلی نیست». همچنان تماشایش کن، فقط با نگاهی نرم‌تر.",
