    "dogsig.alertWatch.means": "هشیار یعنی حواسش جمع است — نه اینکه نقشهٔ حمله دارد. بیشتر سگ‌ها نگاه می‌کنند، تصمیم می‌گیرند و آرام می‌شوند.",
    "dogsig.soundGlance.name": "صدایی شنید",
    "dogsig.soundGlance.look": "سرش ناگهان به سمت پنجره برمی‌گردد",
