    "tour.d3m": "به اندازهٔ کافی نزدیک شو، سگ را بخوان، و بمان تا زنگ خطر فروکش کند. وقتی سؤالی بالای سگ ظاهر شد، روی حسی که فکر می‌کنی دارد ضربه بزن.",
