    "dc.sp.tHab": "به جهش‌ها نگاه کن: هر دویدنِ ناگهانی کمی نرم‌تر از قبلی می‌خورد. همان عنکبوت، همان دویدن — زنگ خطرت دارد یاد می‌گیرد که سریع یعنی «به طرف تو» نیست.",
    "dc.sp.tSettled": "<b>فروکش کرد.</b> همان عنکبوت، همان فاصله — زنگ خطری آرام‌تر. نه با آن جنگیدی نه فرار کردی. ماندی، و بدنت بقیه‌اش را انجام داد.",
