    "primer.sp.lede": "فوبیا زنگ خطری است که درسِ اشتباهی گرفته. ترس از عنکبوت یکی از رایج‌ترین ترس‌هاست — و یکی از درمان‌پذیرترین‌ها.",
    "primer.sp.t1": "یک عنکبوت پیدا می‌شود", "primer.sp.t2": "«دارد می‌آید سراغم. از رویم بالا می‌رود.»",
    "primer.sp.t3": "زنگ خطر به صدا درمی‌آید: پوست مورمور، قلب می‌پرد", "primer.sp.t4": "اتاق را ترک می‌کنی — یا کسی دیگر حسابش را می‌رسد",
    "primer.sp.t5": "آسودگی — زنگ خطر خاموش می‌شود", "primer.sp.t6": "مغزت آن را «درست به‌موقع در رفتم» ثبت می‌کند. عنکبوت بعدی زودتر آژیر را راه می‌اندازد — حتی عکسش.",
    "primer.sp.o1": "یک عنکبوت پیدا می‌شود", "primer.sp.o2": "«به طرفم می‌دود؟» — یک حدس، و آن را امتحان می‌کنی",
    "primer.sp.o3": "زنگ خطر به صدا درمی‌آید — و تو می‌مانی", "primer.sp.o4": "اوج می‌گیرد، بعد خودش پایین می‌آید",
    "primer.sp.o5": "تماشا می‌کنی واقعاً کجا می‌رود (بیشتر وقت‌ها: دور، یا هیچ‌جا)", "primer.sp.o6": "خاطره‌ای تازه: «عنکبوت‌ها سرشان به کار خودشان است.» بعدی نرم‌تر می‌خورد.",
    "primer.sp.simH": "امتحانش کن: سه عنکبوت پشت سر هم. وقتی زنگ خطر اوج می‌گیرد چه می‌کنی؟",
    "primer.sp.dog1": "عنکبوت ۱", "primer.sp.dog2": "عنکبوت ۲", "primer.sp.dog3": "عنکبوت ۳",
    "primer.sp.leaveNote": "هر بار آسودگی — و هر عنکبوتِ بعدی <b>سخت‌تر</b> می‌خورد. رفتن یک دقیقه جواب می‌دهد و برخوردِ بعدی را از تو می‌گیرد.",
    "primer.sp.stayNote": "بالا، بعد خودش پایین — و هر عنکبوتِ بعدی <b>نرم‌تر</b> می‌خورد. همان زنگ خطر، در حال یادگیری. این یعنی مواجهه.",
    "primer.sp.whereH": "از کجا می‌آید",
    "primer.sp.where": "اغلب با تماشا یاد گرفته می‌شود — پدر یا مادری که از عنکبوت جیغ می‌کشید، آن را بی‌کلام یاد می‌دهد. گاهی یک ترسِ ناگهانی است. حرکتِ سریع و غیرقابل‌پیش‌بینی بقیه‌اش را می‌سازد. هر طور شروع شده باشد، به همین شکل باز می‌شود.",
    "primer.sp.practH": "اینجا چه چیزی را تمرین می‌کنی",
    "primer.sp.pract": "👁 خواندنِ عنکبوت — در حال استراحت، در راه جایی، یا ترسیده.<br>〰 گذاشتن که زنگ خطر بالا برود و پایین بیاید، بی‌آنکه بروی.<br>🧪 سنجیدنِ پیش‌بینیِ ترست در برابر جایی که عنکبوت واقعاً می‌رود.",
    "primer.sp.foot": "این تمرینی برای کنجکاوی و شجاعت است، نه درمان — اما همان روشی است که درمانگرها به کار می‌برند، و برای ترس از عنکبوت به‌طور شگفت‌انگیزی خوب جواب می‌دهد.",
    "keep.sp.kicker": "🌿 زیرزمین را باز نگه دار",
    "keep.sp.l1": "<b>هر هفته عمداً دنبال یک عنکبوت بگرد.</b> تاری در گوشهٔ پنجره، یکی روی دیوار باغ، عکسی که قبلاً سریع رد می‌کردی. عنکبوت‌های مختلف در جاهای مختلف، درس را گسترده‌تر یاد می‌دهند.",
    "keep.sp.l2": "<b>آخرین عادت‌های ایمنی را کنار بگذار.</b> گشتنِ تخت، تکاندنِ کفش، ترک اتاق تا کسی دیگر کار را تمام کند — هر کدام را یک بار بدونش امتحان کن.",

