    "level.spiders.0.title": "یک نقطهٔ ریز، دور", "level.spiders.0.desc": "زیرزمینی نیمه‌تاریک. چیزی کوچک در گوشهٔ دور.",
    "level.spiders.1.title": "عنکبوت کوچک، نزدیک", "level.spiders.1.desc": "یک عنکبوت کوچک روی بتن. جابه‌جا می‌شود، بعد ساکن می‌ماند.",
    "level.spiders.2.title": "عنکبوت متوسط، می‌دود", "level.spiders.2.desc": "حالا نزدیک‌تر — و وقتی حرکت می‌کند ناگهان می‌دود.",
    "level.spiders.3.title": "عنکبوت بزرگ، نزدیک", "level.spiders.3.desc": "یک عنکبوت درشت، نزدیک پاهایت. کار کردنِ پاهایش را می‌بینی.",
    "level.spiders.4.title": "روی دیوار، کنار تو", "level.spiders.4.desc": "روی دیوار، درست هم‌سطح چشمت. پاهایش می‌لرزند.",
    "level.snakes.0.title": "ماری که دور آفتاب می‌گیرد", "level.snakes.0.desc": "روی سنگی گرم آن سرِ چمن‌زار. حلقه‌زده، ساکن، زیر آفتاب.",
    "level.snakes.1.title": "در محدودهٔ خودش جابه‌جا می‌شود", "level.snakes.1.desc": "کمی نزدیک‌تر. گاه‌گاهی کمی می‌لغزد، بعد دوباره آرام می‌گیرد.",
    "level.snakes.2.title": "از جلوی مسیر رد می‌شود", "level.snakes.2.desc": "جلوی تو از عرض مسیر می‌لغزد، زبان‌زنان، بعد هوا را می‌خواند.",
    "level.snakes.3.title": "بلند می‌شود و تماشایت می‌کند", "level.snakes.3.desc": "چند متر آن‌طرف‌تر. وقتی نزدیک می‌شوی سرش را بالا می‌آورد، به چشمت خیره می‌ماند و آهسته فس‌فس می‌کند.",
    "level.snakes.4.title": "نزدیک، حلقه‌زده، هوشیار", "level.snakes.4.desc": "درست روی مسیر. اگر با عجله بروی، برای نیش زدن جمع می‌شود؛ اگر آهسته بمانی، آرام می‌گیرد.",

    // Trial names + descriptions (dogs)
    "level.dogs.0.title": "سگ کوچک، دور",
    "level.dogs.0.desc": "یک سگ کوچک آن سرِ اتاق، سرگرم کار خودش.",
    "level.dogs.1.title": "سگ کوچک، نزدیک",
    "level.dogs.1.desc": "همان سگ کوچک. این بار خودش می‌آید تا تو را ببیند.",
    "level.dogs.2.title": "سگ بزرگ‌تر، گوش‌به‌زنگ",
    "level.dogs.2.desc": "یک سگ بزرگ‌تر، دراز کشیده. وقتی بلند می‌شود، گوش‌هایش تیز است و تماشا می‌کند.",
    "level.dogs.3.title": "سگ بزرگ، نزدیک",
    "level.dogs.3.desc": "یک سگ بزرگ که از نزدیک دنبالت می‌کند — و گاهی پارس می‌کند.",
    "level.dogs.4.title": "سگ بزرگ، پارس‌کنان",
    "level.dogs.4.desc": "یک سگ بزرگ، پرسروصدا و هیجان‌زده. پارس می‌کند، می‌جهد — و فاصله را تو انتخاب می‌کنی.",

