    "primer.aria": "ترس از سگ چطور کار می‌کند",
    "primer.kicker": "🧭 یک دقیقه پیش از حیاط",
    "primer.title": "ترس از سگ چطور کار می‌کند — و چطور باز می‌شود",
    "primer.lede": "فوبیا زنگ خطری است که درس اشتباهی گرفته. ضعف نیست، و همیشگی هم نیست: زنگ خطرها می‌توانند دوباره یاد بگیرند.",
    "primer.trapH": "تله",
    "primer.t1": "سگی پیدا می‌شود",
    "primer.t2": "«الان گازم می‌گیرد.»",
    "primer.t3": "زنگ خطر به صدا درمی‌آید: قلب، نفس، پاها",
    "primer.t4": "از آن طرف خیابان می‌روی",
    "primer.t5": "آسودگی — زنگ خطر خاموش می‌شود",
    "primer.t6": "مغزت آن را «درست به‌موقع فرار کردم» ثبت می‌کند. سگ بعدی زودتر زنگ را به صدا درمی‌آورد.",
    "primer.outH": "راه بیرون",
    "primer.o1": "سگی پیدا می‌شود",
    "primer.o2": "«گازم می‌گیرد؟» — یک حدس، و آن را می‌سنجی",
    "primer.o3": "زنگ خطر به صدا درمی‌آید — و تو می‌مانی",
    "primer.o4": "اوج می‌گیرد، بعد خودش پایین می‌آید",
    "primer.o5": "می‌بینی سگ واقعاً چه می‌کند",
    "primer.o6": "خاطرهٔ تازه: «سگ‌ها بیشترشان مشکلی ندارند.» سگ بعدی آرام‌تر می‌زند.",
    "primer.simH": "امتحانش کن: سه سگ پشت سر هم. وقتی زنگ خطر اوج می‌گیرد چه می‌کنی؟",
    "primer.dog1": "سگ ۱",
    "primer.dog2": "سگ ۲",
    "primer.dog3": "سگ ۳",
    "primer.leave": "↩ وقتی اوج گرفت، برو",
    "primer.stay": "🧍 بمان تا پایین بیاید",
    "primer.simHint": "یکی را انتخاب کن و زنگ خطر را تماشا کن.",
    "primer.leaveNote": "هر بار آسودگی — و هر سگ بعدی <b>سخت‌تر</b> می‌زند. فرار یک دقیقه جواب می‌دهد و هزینه‌اش را در برخورد بعدی می‌پردازی.",
    "primer.stayNote": "بالا، بعد خودش پایین — و هر سگ بعدی <b>آرام‌تر</b> می‌زند. همان زنگ خطر، در حال یادگیری. این یعنی مواجهه.",
    "primer.whereH": "از کجا می‌آید",
    "primer.where": "یک لحظهٔ ترسناک با یک سگ، دیدن ترس کس دیگر، یا شنیدن اینکه سگ‌ها خطرناک‌اند — هر کدام می‌تواند شروعش کند. خیلی‌ها یادشان نیست چطور شروع شد. در هر حال، به همان شکل هم از یاد می‌رود.",
    "primer.practH": "اینجا چه تمرین می‌کنی",
    "primer.pract": "👁 خواندن سگ‌ها — آرام، هشیار، یا خواهانِ فاصله.<br>〰 گذاشتن اینکه زنگ خطر بالا برود و پایین بیاید، بدون رفتن.<br>🧪 سنجیدن پیش‌بینیِ ترس با کاری که سگ واقعاً می‌کند.",
    "primer.foot": "این تمرینی برای کنجکاوی و شجاعت است، نه درمان — اما همان روشی است که درمانگرها به کار می‌برند. اگر سگی واقعاً به تو آسیب زده، این را کنار یک متخصص انجام بده.",
    "primer.later": "فعلاً رد کن",
    "primer.close": "بستن",
    "primer.go": "فهمیدم — برویم سراغ اولین آزمون",
    "keep.aria": "نگه داشتنش",
    "keep.kicker": "🌿 حیاط را باز نگه دار",
    "keep.title": "ترس با استفاده کم‌رنگ می‌شود — پس به استفاده ادامه بده",
    "keep.l1": "<b>هر هفته یک سگ ببین.</b> هر سگی، هر اندازه‌ای، هر فاصله‌ای. سگ‌ها و جاهای تازه این درس را گسترده‌تر یاد می‌دهند تا تکرارِ همان یکی.",
    "keep.l2": "<b>آخرین عادت‌های امنیتی را کنار بگذار.</b> همیشه سگ را در دید نگه داشتن، بازوی کسی را گرفتن، اول خیابان را چک کردن — هر کدام را یک بار بدون آن امتحان کن.",
    "keep.l3": "<b>یک روز بد، لغزش است نه بازگشت.</b> یک سگ پرسروصدا یا یک هفتهٔ سخت می‌تواند زنگ خطر را مدتی برگرداند. طبیعی است. یک پله برگرد و دوباره بالا برو — بار دوم سریع‌تر برمی‌گردد.",
    "keep.l4": "<b>یک ماه دیگر دوباره در آینه نگاه کن.</b> عددِ آن بیرون است که اهمیت دارد.",
    "keep.ok": "نگهش می‌دارم",

