    "level.dark.0.title": "اتاقی کم‌نور", "level.dark.0.desc": "اتاق‌خوابت در شب. چراغ کنار تخت روشن است.",
    "level.dark.1.title": "پرده‌ها کشیده", "level.dark.1.desc": "فقط یک چراغ‌خواب کنار دیوار. سایه‌های بلند.",
