    "narb.dogs.arrival.0": "وارد اتاق شدی. سگ این‌جاست، سرش به کار خودش گرم است.",
    "narb.dogs.arrival.1": "یک لحظه وقت بگذار. پیش از رفتن، اتاق را ببین.",
    "narb.dogs.walking.0": "داری به طرف سگ می‌روی. آرام. عجله‌ای نیست.",
    "narb.dogs.walking.1": "بدنت دارد یاد می‌گیرد که سگ آرام است. همین سرعت را نگه دار.",
