    "narb.dogs.close.1": "سگ تو را می‌بیند. می‌توانی نوازشش کنی، یا فقط همین‌جا بایستی.",
    "narb.dogs.panic.0": "سگ آرام است. در امانی. دمی آرام.",
    "narb.dogs.panic.1": "هر وقت خواستی عقب برو. فاصله گرفتن مجاز است. هر وقت آماده بودی برگرد.",
    "narb.dogs.threatened.0": "صدایش بلند است. تو هنوز سر پا ایستاده‌ای. نگاهت را نرم کن و نفس بکش.",
    "narb.dogs.threatened.1": "پارسش بلند است. اگر فاصله لازم داری آرام عقب برو — اختیار دست توست.",
